LinkedBuffer ensureCapacity(int additionalCapacity, LinkedBuffer lb) {
    if (lb.offset + additionalCapacity > lb.buffer.length) {
        int newSize = Math.max(lb.buffer.length << 1, lb.offset + additionalCapacity);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(lb.buffer, 0, newBuffer, 0, lb.offset);
        lb = lb.next = new LinkedBuffer(newBuffer);
    }
    return lb;
}

