List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    boolean isAbsolute = path.startsWith("/");
    String[] segments = path.substring(isAbsolute ? 1 : 0).split("/");
    for (String segment : segments) {
        String decodedSegment = decode ? decode(segment) : segment;
        pathSegments.add(new PathSegmentImpl(decodedSegment, null));
    }
    return pathSegments;
}

